// A Corsair flown low and level over the huts by the Allied airfield,
// about eight metres up: the player is seated in it, switched to the chase
// view, and the plane placed along a straight line every frame
// (`__placeAircraft`). In the cockpit view the page draws the cockpit's
// parts at the eye, and from a camera on the ground the plane was in
// pieces; flown by the flight model this slow it stalled. Wake's sun is
// to the north at 30 degrees, so the shadow falls 1.7 times the height to
// the south, toward a camera thirty metres up south of the line, turned to
// the point between the plane and its shadow. From the ground (either side)
// the shadow fell behind rolling ground or huts.
const P = window.__pass ??= { owner: 820, from: [1350, 124.5, -760], speed: 25, yaw: -Math.PI / 2, at: [1392, 150, -822] };
if (!window.__plane?.()) {
  if (!P.spawned) { P.spawned = true; window.__deploy.selectAny(); window.__deploy.spawn(); }
  else { const v = window.__vehicles().find(v => v.owner === P.owner); window.__setFly?.(true); window.__teleport(v.pos[0] + 3, v.pos[1] + 1, v.pos[2], 0); window.__enterOwner(P.owner); }
}
if (window.__plane?.() && !P.chase) { P.chase = true; window.__setView?.('chase'); }
const x = P.from[0] + P.speed * s, y = P.from[1], z = P.from[2];
if (window.__plane?.()) window.__placeAircraft(x, y, z, P.yaw, P.speed);
// The shadow: the ground point under the plane along the sun's rays (Wake's
// sun direction, toward the sun, -0.295 0.496 0.816).
const h = Math.max(0, y - window.__groundAt(x, z));
const sx = x + 0.595 * h, sz = z - 1.645 * h, sy = window.__groundAt(sx, sz);
const at = P.at, dx = (sx + x) / 2 - at[0], dy = (sy + y) / 2 - at[1], dz = (sz + z) / 2 - at[2];
window.__shotCamera = cam => {
  const T = window.__THREE;
  const q = new T.Quaternion().setFromEuler(new T.Euler(Math.atan2(dy, Math.hypot(dx, dz)), Math.atan2(-dx, -dz), 0, 'YXZ'));
  const m = new T.Matrix4().compose(new T.Vector3(...at), q, new T.Vector3(1, 1, 1));
  if (cam.parent) { cam.parent.updateMatrixWorld(true); m.premultiply(cam.parent.matrixWorld.clone().invert()); }
  m.decompose(cam.position, cam.quaternion, cam.scale);
  cam.updateMatrixWorld(true);
};

