// A Kubelwagen parked under a barn's lean-to at the German base, set
// burning (`__damageVehicle` to 3 of its 50 hit points, under its fire tier
// of 6) and held there: below its critical hit points a car burns down and
// blows up, which is not this shot. Kharkov's dim light (ambient 0.02) is
// where a fire's own light shows. The camera circles it slowly.
const F = window.__fire ??= { owner: 952, hold: 3, p: null };
const v = window.__vehicles().find(v => v.owner === F.owner);
if (!F.p) F.p = v.pos;
if (Math.abs(v.hp - F.hold) > 0.5) window.__damageVehicle(F.owner, v.hp - F.hold);
const a = 3.5 + s * 0.06, [px, py, pz] = F.p;
const at = [px + Math.sin(a) * 7.5, py + 1.7, pz + Math.cos(a) * 7.5];
const dx = px - at[0], dy = py + 0.4 - at[1], dz = pz - at[2];
window.__shotCamera = cam => {
  const T = window.__THREE;
  const q = new T.Quaternion().setFromEuler(new T.Euler(Math.atan2(dy, Math.hypot(dx, dz)), Math.atan2(-dx, -dz), 0, 'YXZ'));
  const m = new T.Matrix4().compose(new T.Vector3(...at), q, new T.Vector3(1, 1, 1));
  if (cam.parent) { cam.parent.updateMatrixWorld(true); m.premultiply(cam.parent.matrixWorld.clone().invert()); }
  m.decompose(cam.position, cam.quaternion, cam.scale);
  cam.updateMatrixWorld(true);
};

